// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.assume(nonOwner != address(this) && nonOwner != address(c) && nonOwner.code.length == 0);

        vm.deal(address(c), amount);
        vm.prank(address(this));
        c.sendMoney(address(this), amount);

        vm.deal(nonOwner, 0);
        vm.prank(nonOwner);
        try c.withdrawAll() {
            assertTrue(false);
        } catch {
            assertTrue(true);
        }
    }
}
